// Both wrappers merge their arguments into one props object. Neither creates a
// reactive source: a merge carries whatever its sources carry, which is exactly
// why the contract's claim names an argument instead of asserting a store.
//
// The signatures are `tsc`-clean on purpose. Destructuring the result is a
// well-typed expression under the real published typings of every wrapper of
// this shape, so nothing here duplicates a type diagnostic.
export declare function withDefaults<T extends object>(base: T): T & { label: string };
// Reaches through to argument *1*, not 0. Same shape, different index, so a
// consumer that ignored the index could not tell the two apart.
export declare function withOverrides<T extends object>(base: object, overrides: T): T & object;
